#!/usr/bin/env python3
"""Generate full diploma .docx — v3 (with screenshots, listings, page numbers)"""

import os
from docx import Document
from docx.shared import Pt, Cm, Inches, Emu
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn, nsdecls
from docx.oxml import parse_xml

doc = Document()
style = doc.styles['Normal']
style.font.name = 'Times New Roman'
style.font.size = Pt(14)
style.paragraph_format.line_spacing = 1.5
style.paragraph_format.space_after = Pt(0)
style.paragraph_format.space_before = Pt(0)
for s in doc.sections:
    s.left_margin = Cm(3); s.right_margin = Cm(1); s.top_margin = Cm(2); s.bottom_margin = Cm(2)

# ---- Page numbers in footer ----
def add_page_numbers(section):
    footer = section.footer
    footer.is_linked_to_previous = False
    p = footer.paragraphs[0]
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run()
    fld_xml = (
        '<w:fldSimple {} w:instr=" PAGE " w:dirty="true">'
        '<w:r><w:rPr><w:sz w:val="24"/></w:rPr><w:t>1</w:t></w:r></w:fldSimple>'
    ).format(nsdecls('w'))
    run._r.addnext(parse_xml(fld_xml))

for section in doc.sections:
    add_page_numbers(section)

def cf(cell, size=Pt(11), bold=False):
    for p in cell.paragraphs:
        for r in p.runs:
            r.font.name = 'Times New Roman'; r.font.size = size; r.font.bold = bold

def P(text, bold=False, size=14, align=None, indent=Cm(1.25)):
    par = doc.add_paragraph()
    run = par.add_run(text)
    run.font.name = 'Times New Roman'; run.font.size = Pt(size); run.bold = bold
    par.paragraph_format.line_spacing = 1.5
    par.paragraph_format.first_line_indent = indent if indent is not None else Cm(0)
    if align: par.alignment = align
    return par

def H1(text):
    p = doc.add_paragraph()
    r = p.add_run(text); r.bold = True; r.font.name = 'Times New Roman'; r.font.size = Pt(16)
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.line_spacing = 1.5; p.paragraph_format.first_line_indent = Cm(0); p.paragraph_format.space_before = Pt(24); p.paragraph_format.space_after = Pt(12)

def H2(text):
    p = doc.add_paragraph()
    r = p.add_run(text); r.bold = True; r.font.name = 'Times New Roman'; r.font.size = Pt(14)
    p.paragraph_format.line_spacing = 1.5; p.paragraph_format.first_line_indent = Cm(1.25); p.paragraph_format.space_before = Pt(12); p.paragraph_format.space_after = Pt(6)

def E():
    p = doc.add_paragraph(); p.paragraph_format.line_spacing = 1.5; p.paragraph_format.first_line_indent = Cm(0)
    p.add_run('').font.name = 'Times New Roman'

def PB(): doc.add_page_break()

def TBL(headers, data, caption, fs=11):
    E()
    cap = doc.add_paragraph()
    r = cap.add_run(caption); r.bold = True; r.font.name = 'Times New Roman'; r.font.size = Pt(12)
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER; cap.paragraph_format.first_line_indent = Cm(0)
    t = doc.add_table(rows=1+len(data), cols=len(headers)); t.style = 'Table Grid'
    for i,h in enumerate(headers): c = t.rows[0].cells[i]; c.text = h; cf(c, bold=True)
    for ri,row in enumerate(data):
        for ci,val in enumerate(row): c = t.rows[ri+1].cells[ci]; c.text = val; cf(c)
    E()

def CODE(text, label=None):
    """Add code listing with monospace font in Appendix B"""
    if label:
        p = doc.add_paragraph()
        r = p.add_run(label); r.bold = True; r.font.name = 'Times New Roman'; r.font.size = Pt(12)
        p.paragraph_format.first_line_indent = Cm(0)
        p.paragraph_format.space_before = Pt(6)
    # code block
    for line in text.split('\n'):
        par = doc.add_paragraph()
        run = par.add_run(line)
        run.font.name = 'Courier New'
        run.font.size = Pt(8)
        par.paragraph_format.line_spacing = 1.0
        par.paragraph_format.first_line_indent = Cm(0)
        par.paragraph_format.space_after = Pt(0)
        par.paragraph_format.space_before = Pt(0)

def IMG(path, caption):
    """Add screenshot image"""
    E()
    if os.path.exists(path):
        doc.add_picture(path, width=Inches(5.5))
    else:
        P(f'[Файл {path} не найден]', indent=None)
    p = doc.add_paragraph()
    r = p.add_run(caption); r.bold = False; r.font.name = 'Times New Roman'; r.font.size = Pt(12)
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.first_line_indent = Cm(0)
    E()

# ========== TITLE (placeholder — user fills in Word) ==========
for _ in range(5): E()
P('[НАИМЕНОВАНИЕ ВУЗА]', bold=True, size=14, align=WD_ALIGN_PARAGRAPH.CENTER, indent=None)
E()
P('[Факультет/Институт]', size=14, align=WD_ALIGN_PARAGRAPH.CENTER, indent=None)
P('[Кафедра]', size=14, align=WD_ALIGN_PARAGRAPH.CENTER, indent=None)
for _ in range(3): E()
P('ВЫПУСКНАЯ КВАЛИФИКАЦИОННАЯ РАБОТА', bold=True, size=16, align=WD_ALIGN_PARAGRAPH.CENTER, indent=None)
E()
P('на тему: «Разработка информационно-справочной системы\nкультурно-развлекательных центров\nБелгородской области»', bold=True, size=16, align=WD_ALIGN_PARAGRAPH.CENTER, indent=None)
for _ in range(4): E()
P('Обучающийся: [ФИО]', size=14, align=WD_ALIGN_PARAGRAPH.CENTER, indent=None)
P('Руководитель: [ФИО, должность]', size=14, align=WD_ALIGN_PARAGRAPH.CENTER, indent=None)
for _ in range(3): E()
P('Белгород, 2026', size=14, align=WD_ALIGN_PARAGRAPH.CENTER, indent=None)
PB()

# ========== TOC ==========
H1('СОДЕРЖАНИЕ')
for item in ['ВВЕДЕНИЕ','ГЛАВА 1. ТЕОРЕТИЧЕСКИЕ ОСНОВЫ РАЗРАБОТКИ ИНФОРМАЦИОННО-СПРАВОЧНОЙ СИСТЕМЫ',
    '    1.1 Анализ культурно-развлекательной сферы Белгородской области',
    '    1.2 Обзор существующих решений-аналогов',
    '    1.3 Техническое задание на разработку',
    '    Выводы по первой главе',
    'ГЛАВА 2. РЕАЛИЗАЦИЯ ИНФОРМАЦИОННО-СПРАВОЧНОЙ СИСТЕМЫ',
    '    2.1 Выбор и обоснование технологий разработки',
    '    2.2 Процесс разработки',
    '    2.3 Тестирование',
    'ЗАКЛЮЧЕНИЕ','СПИСОК ЛИТЕРАТУРЫ',
    'ПРИЛОЖЕНИЕ А. Скриншоты интерфейса','ПРИЛОЖЕНИЕ Б. Листинги основных модулей']:
    P(item, indent=None)
PB()

# ========== INTRODUCTION ==========
H1('ВВЕДЕНИЕ')

P('В современном мире информационные технологии играют ключевую роль в развитии всех сфер жизнедеятельности общества. Цифровая трансформация затронула такие области, как образование, здравоохранение, государственное управление, бизнес и, безусловно, культуру. Сегодня невозможно представить эффективное функционирование любой отрасли без использования современных информационных систем, обеспечивающих сбор, хранение, обработку и предоставление информации конечным пользователям. В сфере культуры особенно остро стоит проблема обеспечения доступности информации о культурных учреждениях, мероприятиях и услугах для широких слоёв населения.')

P('Белгородская область является одним из наиболее динамично развивающихся регионов Центрального федерального округа. По данным Территориального органа Федеральной службы государственной статистики, численность населения региона составляет более 1,5 миллиона человек, а сеть учреждений культуры включает сотни объектов различного типа и назначения. В регионе функционируют театры, музеи, библиотеки, дворцы культуры, кинотеатры, концертные площадки, филармонии, стадионы, парки культуры и отдыха. Эта инфраструктура формирует единое культурное пространство, однако информация о ней рассредоточена по множеству разрозненных источников, что создаёт объективные трудности для жителей и гостей региона при поиске актуальных сведений о культурном досуге.')

P('На сегодняшний день существует несколько информационных ресурсов, предоставляющих сведения о культурно-развлекательной сфере Белгородской области. К ним относятся официальный портал «Культурный регион» (bel.cultreg.ru), региональные афишные сайты (afishka31.ru), федеральные порталы (culture.ru), а также общие картографические сервисы (Яндекс.Карты, 2ГИС). Однако каждый из перечисленных ресурсов обладает существенными ограничениями. Так, картографические сервисы не предоставляют специализированной информации о культурных учреждениях с возможностью фильтрации именно по культурным категориям. Портал «Культурный регион» содержит подробную базу учреждений, но не имеет интерактивной карты и афиши мероприятий. Афишные сайты, напротив, содержат только расписание событий без привязки к справочной информации об учреждениях. Ни один из существующих ресурсов не объединяет на единой платформе интерактивную карту, каталог учреждений и афишу мероприятий.')

P('Таким образом, существует объективная потребность в создании единой информационно-справочной системы, объединяющей на одной платформе интерактивную карту всех культурно-развлекательных центров региона, каталог учреждений с подробной информацией о каждом объекте и актуальную афишу мероприятий. Подобная система позволит пользователям быстро находить интересующие их учреждения и события, планировать досуг, а органам управления культуры — осуществлять мониторинг и анализ культурной инфраструктуры региона.')

P('Актуальность темы подтверждается государственной политикой в сфере цифровизации культуры. В рамках национального проекта «Культура» и Стратегии развития информационного общества в Российской Федерации особое внимание уделяется созданию общедоступных цифровых ресурсов, обеспечивающих свободный доступ граждан к культурным ценностям и информации о культурных событиях. Разрабатываемая система полностью соответствует данным стратегическим ориентирам и может внести вклад в цифровое развитие культурной сферы Белгородской области.')

P('Целью данной выпускной квалификационной работы является разработка информационно-справочной системы культурно-развлекательных центров Белгородской области в виде веб-приложения с интерактивной картой, каталогом учреждений и афишей мероприятий.')

P('Объектом исследования являются культурно-развлекательные центры Белгородской области. Предметом исследования — процесс разработки веб-приложения для информационно-справочного обеспечения культурно-развлекательных учреждений региона.')

P('Для достижения поставленной цели необходимо решить следующие задачи:')
P('1) провести анализ культурно-развлекательной сферы Белгородской области, выявить основные категории учреждений культуры и определить источники данных;')
P('2) выполнить обзор существующих решений-аналогов и обосновать необходимость разработки собственной системы;')
P('3) разработать техническое задание на создание информационно-справочной системы в соответствии с требованиями ГОСТ 19.201-78 и ГОСТ 34.602-89;')
P('4) обосновать выбор технологического стека для реализации системы;')
P('5) реализовать веб-приложение, включающее интерактивную карту с кластеризацией маркеров, каталог объектов, афишу мероприятий, административную панель и программные модули для импорта и парсинга данных;')
P('6) провести тестирование разработанной системы и оценить её функциональность на соответствие требованиям технического задания.')

P('Практическая значимость работы заключается в создании полнофункционального веб-приложения, доступного по адресу https://kulturnaya-karta-31.onrender.com, которое может быть использовано жителями и гостями Белгородской области для поиска культурно-развлекательных учреждений и планирования досуга, а также органами управления культуры для мониторинга и анализа состояния культурной инфраструктуры региона. Система предоставляет открытый API для интеграции с внешними информационными системами.')

P('Структура работы: выпускная квалификационная работа состоит из введения, двух глав, заключения, списка используемой литературы из 50 наименований и двух приложений. Первая глава посвящена теоретическим основам разработки системы, вторая — практической реализации. Общий объём работы составляет 40 страниц.')
PB()

# ========== CHAPTER 1 ==========
H1('ГЛАВА 1. ТЕОРЕТИЧЕСКИЕ ОСНОВЫ РАЗРАБОТКИ ИНФОРМАЦИОННО-СПРАВОЧНОЙ СИСТЕМЫ')

H2('1.1 Анализ культурно-развлекательной сферы Белгородской области')

P('Белгородская область является одним из наиболее экономически развитых регионов Центрального федерального округа. По данным Территориального органа Федеральной службы государственной статистики по Белгородской области, численность населения региона составляет 1 548 936 человек (по состоянию на 1 января 2026 года), из которых около 67 % проживает в городской местности, а 33 % — в сельской. Административно-территориальное деление включает 21 муниципальный район и 9 городских округов. На территории области расположено более 300 сельских и городских поселений, в каждом из которых в той или иной форме присутствуют учреждения культуры и досуга.')

P('Инфраструктура культурно-развлекательных центров Белгородской области характеризуется значительным разнообразием как по типам учреждений, так и по формам собственности и ведомственной принадлежности. В ходе анализа официальных источников, включая открытые данные портала «Культурный регион» (bel.cultreg.ru), реестры учреждений культуры Министерства культуры Белгородской области, данные картографических сервисов и информационных порталов, были выделены и систематизированы следующие основные категории культурно-развлекательных учреждений, функционирующих на территории региона:')

P('1) Театры — профессиональные театры различных жанров и направлений. В данную категорию входят драматические театры, театры кукол, театры для детей и молодёжи, а также театры-студии. Наиболее известными представителями категории являются Белгородский академический драматический театр имени М.С. Щепкина (один из старейших театров России, основанный в 1936 году), Белгородский государственный театр кукол и Старооскольский театр для детей и молодёжи. Театры являются важнейшими центрами культурной жизни региона, их репертуар охватывает как классические, так и современные постановки.')

P('2) Кинотеатры — городские и районные кинотеатры, киноконцертные залы, а также кинозалы в составе культурно-досуговых центров. Большинство кинотеатров региона расположены в крупных городах (Белгород, Старый Оскол, Губкин), однако в последние годы в рамках программ модернизации культурной инфраструктуры наблюдается тенденция открытия небольших кинозалов в сельской местности, что способствует повышению доступности кинопоказа для сельского населения.')

P('3) Концертные залы — специализированные площадки, предназначенные для проведения концертных программ, музыкальных фестивалей, творческих вечеров и гастрольных выступлений. Данная категория включает как отдельные концертные залы, так и концертные площадки в составе других учреждений культуры.')

P('4) Филармонии — учреждения, основными задачами которых являются организация концертной деятельности и пропаганда классического и современного музыкального искусства. Единственным представителем данной категории в регионе является Белгородская государственная филармония, включающая Большой, Малый и Органный залы.')

P('5) Стадионы и спорткомплексы — многофункциональные спортивные сооружения, используемые не только для проведения спортивных соревнований, но и для организации концертов, фестивалей и массовых культурных мероприятий. Ключевыми объектами категории являются многофункциональный спортивный комплекс «Белгород Арена» и центральный стадион «Салют» в городе Белгороде.')

P('6) Дворцы культуры и клубы — наиболее многочисленная категория, включающая городские и районные дома культуры, сельские клубы, культурно-досуговые центры, дома народного творчества. Именно эти учреждения являются основными центрами культурной жизни в сельской местности, где они выполняют функции организации досуга, проведения праздников, работы кружков и творческих коллективов.')

P('7) Музеи и выставки — учреждения, осуществляющие комплектование, хранение, изучение и публичное представление музейных предметов и коллекций. Категория включает краеведческие музеи, художественные музеи и галереи, мемориальные музеи, музеи-усадьбы, выставочные залы. Важнейшими музеями региона являются Белгородский государственный историко-краеведческий музей, Белгородский художественный музей, музей-диорама «Курская битва. Белгородское направление».')

P('8) Фестивали и городские мероприятия — данная категория включает регулярные культурные события, фестивали, городские праздники, ярмарки, проводимые на открытых площадках и в общественных пространствах. К числу наиболее значимых событий относятся Международный фестиваль славянской культуры «Хотмыжская осень», фестиваль «Белгородское лето», День города, День Победы и другие массовые мероприятия.')

